        VoiceLine(280, King, ru="Какая разница? Связь с ним утеряна, он, скорее всего погиб.", en="What difference does it make? Contact with him is lost. He's most likely dead."),
        VoiceLine(290, MajorScrew, ru="Тем не менее, генерал.", en="Nevertheless, General."),
        VoiceLine(300, King, ru="Аларик. По-моему, Аларик.", en="Alaric. Alaric, I think."),
        VoiceLine(310, Trent, ru="Сволочи! Что с Алариком, гады?", en="Bastards! What happened to Alaric, you scum?"),
        VoiceLine(320, MajorScrew, ru="Мы не знаем. Связь с ним прервалась где-то на территории Кусари.", en="We don't know. Contact with him was lost somewhere in Kusari territory."),
        VoiceLine(330, Hatcher, ru="(виноватая): У него почти получилось. Он должен был передать нам базу данных, но не вышел на связь. Мы не знаем, кто наложил лапу на Аларика и его информацию.",
                  en="(guilty): He almost managed it. He was supposed to hand us a database, but he never made contact. We don't know who got their hands on Alaric and his information."),
        VoiceLine(340, King, ru="(мотивирующе): Ты можешь помочь и нам и своему другу. Найди его, заверши передачу информации, которую должен был завершить твой друг - и ты свободен.",
                  en="(encouraging): You can help both us and your friend. Find him, finish the information transfer your friend was supposed to finish, and you're free."),
        VoiceLine(345, King, ru="И не вздумай хитрить, дружище, не вздумай", en="And don't you dare get clever, pal. Don't you dare."),
