        VoiceLine(360, King, ru="Мисс Хетчер, поднимите все данные по агенту Аларику и передайте их в распоряжение мистеру Тренту.", en="Miss Hatcher, pull all the data on Agent Alaric and place it at Mister Trent's disposal."),
        VoiceLine(370, King, ru="Далее, вашим заданием будет сопровождение тома Протея вместе с Трентом и мисс Дерси на исследовательскую базу.",
                  en="Next, your assignment will be to escort the Proteus tome, together with Trent and Miss Darcy, to the research base."),
        VoiceLine(380, Hatcher, ru="Принято!", en="Copy!"),
